/* Major biblical figures for in-text detection and the People panel.
   t: "ot" | "nt" | "both" — used to disambiguate names shared across
   testaments (e.g. Saul the king vs. Saul of Tarsus).
   av: avatar style — king|prophet|priest|warrior|woman|elder|shepherd|
       traveler|fisherman|official|youth */
window.BVV = window.BVV || {};

BVV.PEOPLE = [
  { id:"adam", name:"Adam", al:["Adam"], t:"ot", av:"elder", desc:"The first man, formed from dust, placed in Eden as its keeper; his fall brought sin and death into the world." },
  { id:"eve", name:"Eve", al:["Eve"], t:"ot", av:"woman", desc:"'Mother of all living,' formed from Adam's side; deceived by the serpent, yet promised a seed who would crush it." },
  { id:"noah", name:"Noah", al:["Noah"], t:"ot", av:"elder", desc:"Righteous in a violent generation; built the ark over decades of preaching and became humanity's second head." },
  { id:"cain", name:"Cain", al:["Cain"], t:"ot", av:"elder", desc:"Adam and Eve's firstborn, a farmer whose rejected offering curdled into rage; killed his brother Abel and was sent off marked and wandering." },
  { id:"abel", name:"Abel", al:["Abel"], t:"ot", av:"shepherd", desc:"Second son of Adam and Eve, a shepherd whose favored offering made him history's first murder victim, killed by his own brother." },
  { id:"seth", name:"Seth", al:["Seth"], t:"ot", av:"elder", desc:"Third son of Adam and Eve, given 'in place of Abel'; his line carried the name of the LORD forward to Noah." },
  { id:"enoch-son-cain", name:"Enoch (son of Cain)", al:["Enoch"], t:"ot", av:"elder", desc:"Cain's son, for whom Cain named the first city mentioned in Scripture." },
  { id:"lamech-cainite", name:"Lamech (son of Methushael)", al:["Lamech"], t:"ot", av:"elder", desc:"Cain's violent descendant, first polygamist named in the Bible, who boasted to his wives of killing a man and claimed seventy-sevenfold vengeance." },
  { id:"jabal", name:"Jabal", al:["Jabal"], t:"ot", av:"shepherd", desc:"Lamech's son by Adah; ancestor of those who dwell in tents and keep livestock." },
  { id:"jubal", name:"Jubal", al:["Jubal"], t:"ot", av:"elder", desc:"Lamech's son by Adah; father of all who play the harp and flute." },
  { id:"tubal-cain", name:"Tubal-cain", al:["Tubal-cain","Tubal-Cain"], t:"ot", av:"elder", desc:"Lamech's son by Zillah; forger of every tool of bronze and iron." },
  { id:"enosh", name:"Enosh", al:["Enosh"], t:"ot", av:"elder", desc:"Seth's son, born in whose days 'people began to call upon the name of the LORD.'" },
  { id:"enoch-son-jared", name:"Enoch (son of Jared)", al:["Enoch"], t:"both", av:"elder", desc:"Seventh from Adam in Seth's line; 'walked with God, and he was not, for God took him' without dying." },
  { id:"methuselah", name:"Methuselah", al:["Methuselah"], t:"ot", av:"elder", desc:"Enoch's son and the longest-lived person in Scripture at 969 years; his death year, by traditional chronology, coincides with the Flood." },
  { id:"lamech-sethite", name:"Lamech (father of Noah)", al:["Lamech"], t:"ot", av:"elder", desc:"Methuselah's son who named his own son Noah, hoping for relief from the toil of the cursed ground." },
  { id:"shem", name:"Shem", al:["Shem"], t:"ot", av:"elder", desc:"Noah's eldest son, ancestor of the Semitic peoples and, through Arphaxad and Eber, of Abraham himself." },
  { id:"ham", name:"Ham", al:["Ham"], t:"ot", av:"elder", desc:"Noah's son whose disrespect toward his drunken father brought a curse on his son Canaan; ancestor of Egypt, Cush, and Canaan." },
  { id:"japheth", name:"Japheth", al:["Japheth"], t:"ot", av:"elder", desc:"Noah's son, ancestor of the maritime and northern peoples who spread out across the coastlands." },
  { id:"canaan-person", name:"Canaan", al:["Canaan"], t:"ot", av:"elder", desc:"Ham's son, cursed by Noah to serve his brothers' lines; ancestor of the peoples later dispossessed at the conquest." },
  { id:"nimrod", name:"Nimrod", al:["Nimrod"], t:"ot", av:"warrior", desc:"Cush's son, 'a mighty hunter before the LORD,' whose kingdom began at Babel and stretched on to found Nineveh." },
  { id:"peleg", name:"Peleg", al:["Peleg"], t:"ot", av:"elder", desc:"Descendant of Shem through Eber, named because 'in his days the earth was divided' — traditionally linked to Babel's scattering." },
  { id:"terah", name:"Terah", al:["Terah"], t:"ot", av:"elder", desc:"Shem's descendant, father of Abram, Nahor, and Haran; led his family from Ur toward Canaan but settled and died in Haran." },
  { id:"abraham", name:"Abraham", al:["Abraham","Abram"], t:"ot", av:"elder", desc:"Called from Ur to a land he'd never seen; father of the faithful, to whom God swore covenant blessing for all nations." },
  { id:"sarah", name:"Sarah", al:["Sarah","Sarai"], t:"ot", av:"woman", desc:"Abraham's wife, barren until ninety, who laughed at the promise and then named her son 'laughter' (Isaac)." },
  { id:"isaac", name:"Isaac", al:["Isaac"], t:"ot", av:"shepherd", desc:"The long-promised son, nearly sacrificed on Moriah; a quiet well-digger who carried the covenant to the next generation." },
  { id:"jacob", name:"Jacob", al:["Jacob"], t:"ot", av:"shepherd", desc:"The heel-grabbing twin who bargained, fled, wrestled God at the Jabbok, and limped away renamed Israel — father of the twelve tribes." },
  { id:"joseph-ot", name:"Joseph (son of Jacob)", al:["Joseph"], t:"ot", av:"official", desc:"Sold by his brothers, raised from Egyptian prison to vizier; his grain administration saved the family that betrayed him." },
  { id:"moses", name:"Moses", al:["Moses"], t:"both", av:"prophet", desc:"Prince of Egypt turned desert shepherd, then liberator, lawgiver and mediator who spoke with God face to face." },
  { id:"aaron", name:"Aaron", al:["Aaron"], t:"ot", av:"priest", desc:"Moses' brother and spokesman; first high priest, wearing the ephod and breastpiece with the Urim and Thummim." },
  { id:"jethro", name:"Jethro", al:["Jethro","Reuel","Hobab"], t:"ot", av:"priest", desc:"Priest of Midian and Moses' father-in-law, whose flock Moses was tending at Horeb when God called him from the burning bush; also named Reuel (Ex 2:18), and later, through his son Hobab, guides Israel's wilderness march (Num 10:29)." },
  { id:"pharaoh-exodus", name:"Pharaoh (the Exodus)", al:["Pharaoh"], t:"ot", av:"king", desc:"Egypt's king through the ten plagues, whose repeatedly hardened heart holds Israel until his own firstborn son dies at midnight; he then summons Moses and Aaron in the dark to drive Israel out at once (Exod 12:31-32). Not named in the text; often associated with Amenhotep II or Rameses II depending on the Exodus date proposed." },
  { id:"levites", name:"The Levites", al:["Levites","tribe of Levi","sons of Levi"], t:"ot", av:"priest", desc:"Jacob and Leah's third son Levi's descendants; the only tribe to rally to Moses' call 'Who is on the LORD's side?' after the golden calf, executing about three thousand covenant-breakers at his command (Exod 32:26-29) — loyalty later cited (Deut 33:8-11) as the reason this tribe alone is set apart for the priesthood and tabernacle service, receiving no tribal land allotment of its own (Num 18:20-24)." },
  { id:"joshua", name:"Joshua", al:["Joshua"], t:"ot", av:"warrior", desc:"Moses' aide and war leader who took Israel across the Jordan and apportioned the land." },
  { id:"deborah", name:"Deborah", al:["Deborah"], t:"ot", av:"woman", desc:"Prophetess and judge who summoned Barak; sang the victory over Sisera's chariots by the Kishon." },
  { id:"gideon", name:"Gideon", al:["Gideon","Jerubbaal"], t:"ot", av:"warrior", desc:"Threshing wheat in a winepress when called; routed Midian with 300 men, torches and trumpets at the spring of Harod." },
  { id:"samson", name:"Samson", al:["Samson"], t:"ot", av:"warrior", desc:"Nazirite strongman of Dan whose one-man war on the Philistines ended blind at Gaza — and in one final collapse of Dagon's temple." },
  { id:"ruth", name:"Ruth", al:["Ruth"], t:"ot", av:"woman", desc:"Moabite widow who clung to Naomi and Naomi's God; gleaned in Boaz's barley fields and became David's great-grandmother." },
  { id:"naomi", name:"Naomi", al:["Naomi","Mara"], t:"ot", av:"woman", desc:"Elimelech's widow, driven to Moab by famine and back to Bethlehem by grief; renamed herself Mara ('bitter') on her return, then lived to nurse her redeemed grandson Obed, David's grandfather (Ruth 1, 4)." },
  { id:"boaz", name:"Boaz", al:["Boaz"], t:"ot", av:"elder", desc:"Prosperous Bethlehemite kinsman of Elimelech; his kindness to Ruth in the barley fields led him to redeem the family's land and marry her at the city gate, fathering Obed and entering David's line (Ruth 2-4; Matt 1:5)." },
  { id:"elimelech", name:"Elimelech", al:["Elimelech"], t:"ot", av:"elder", desc:"Bethlehemite husband of Naomi who moved his family to Moab during a famine and died there, leaving Naomi and two sons (Ruth 1:2-3)." },
  { id:"mahlon", name:"Mahlon", al:["Mahlon"], t:"ot", av:"youth", desc:"Elimelech and Naomi's son, Ruth's first husband; died in Moab without children, leaving Ruth a widow (Ruth 1:2-5; 4:10)." },
  { id:"chilion", name:"Chilion", al:["Chilion"], t:"ot", av:"youth", desc:"Elimelech and Naomi's son, married to Orpah; died in Moab alongside his brother Mahlon, leaving both wives childless widows (Ruth 1:2-5)." },
  { id:"orpah", name:"Orpah", al:["Orpah"], t:"ot", av:"woman", desc:"Naomi's Moabite daughter-in-law who, unlike Ruth, accepted Naomi's urging and turned back to her own people and gods (Ruth 1:4, 14-15)." },
  { id:"obed", name:"Obed", al:["Obed"], t:"ot", av:"youth", desc:"Son of Boaz and Ruth, nursed by Naomi and celebrated by the women of Bethlehem as 'a son... born to Naomi'; father of Jesse and grandfather of David (Ruth 4:13-17, 21-22)." },
  { id:"nearer-redeemer", name:"The nearer redeemer", al:["the redeemer","the closer kinsman","Mr. So-and-so"], t:"ot", av:"elder", desc:"An unnamed relative of Elimelech closer in line than Boaz — first willing to redeem the family land, then declining once he learns the redemption includes marrying Ruth and raising up an heir, for fear of damaging his own inheritance (Ruth 4:1-6)." },
  { id:"hannah", name:"Hannah", al:["Hannah"], t:"ot", av:"woman", desc:"Wept before the LORD at Shiloh for a son; lent Samuel to God and sang the song Mary would echo." },
  { id:"eli", name:"Eli", al:["Eli"], t:"ot", av:"priest", desc:"High priest at Shiloh who raised Samuel; died at news of the ark's capture." },
  { id:"samuel", name:"Samuel", al:["Samuel"], t:"ot", av:"prophet", desc:"Last judge and first of the great prophets: Hannah's answered prayer, raised at the Shiloh sanctuary, kingmaker to Saul and David. He anointed Saul, announced his rejection (1 Sam 15), and even in death — summoned at En-dor — his word to Saul did not change." },
  { id:"saul", name:"Saul", al:["Saul"], t:"ot", av:"king", desc:"Israel's first king — head and shoulders above the people, from little Benjamin. Anointed in private over lost donkeys, confirmed by lot at Mizpah, his early victories gave way to disobedience (Amalek), the Spirit's departure, jealous pursuit of David, and a final desperate night at En-dor before dying on Gilboa." },
  { id:"kish", name:"Kish", al:["Kish"], t:"ot", av:"elder", desc:"Wealthy Benjaminite of Gibeah, Saul's father; his straying donkeys sent Saul on the errand that led, unknowingly, to a king's anointing (1 Sam 9)." },
  { id:"jonathan", name:"Jonathan", al:["Jonathan"], t:"ot", av:"warrior", desc:"Saul's heroic heir who loved David as his own soul and gave him his robe and armor; died beside his father on Gilboa." },
  { id:"david", name:"David", al:["David"], t:"both", av:"king", desc:"Shepherd, psalmist, giant-slayer, outlaw, king. During 1 Samuel 28 he is far south at Ziklag, uneasily mustered with the Philistine army of Achish — providentially dismissed before the battle (1 Sam 29)." },
  { id:"abigail", name:"Abigail", al:["Abigail"], t:"ot", av:"woman", desc:"Nabal's discerning wife whose swift diplomacy stopped David's bloodshed; later his wife." },
  { id:"nabal", name:"Nabal", al:["Nabal"], t:"ot", av:"elder", desc:"Wealthy, harsh Calebite sheep-owner of Maon and Carmel whose name means 'fool' and who lived up to it — refused David's men customary provisions, then died ten days after his heart failed at the news of how close he'd come to ruin (1 Sam 25)." },
  { id:"achish", name:"Achish", al:["Achish"], t:"ot", av:"king", desc:"Philistine king of Gath who sheltered David for sixteen months, made him his bodyguard, and trusted him more than his own lords did (1 Sam 27–29)." },
  { id:"amalekite-messenger", name:"The Amalekite messenger", al:["Amalekite"], t:"ot", av:"traveler", desc:"A sojourner among the Amalekites who brings David news of Saul's death at Gilboa, claiming — falsely, against 1 Sam 31's own account — that he killed the wounded king himself at Saul's request; David has him executed for lifting a hand against 'the LORD's anointed' (2 Sam 1:1-16)." },
  { id:"jebusites", name:"The Jebusites", al:["Jebusites","Jebusite"], t:"ot", av:"warrior", desc:"Canaanite clan holding the fortress of Jebus/Jerusalem from the conquest into David's reign, so confident in its defenses they taunted that 'the blind and the lame' could turn him back — until Joab's men found a way in through the water shaft (2 Sam 5:6-8)." },
  { id:"medium-endor", name:"The medium of En-dor", al:["medium"], t:"ot", av:"woman", desc:"An unnamed woman practicing necromancy in secret after Saul's own purge. Her terrified scream when Samuel actually appeared suggests she expected no such thing; yet she ends the story showing the fallen king a strange kindness — a fattened calf and bread before his last battle." },
  { id:"solomon", name:"Solomon", al:["Solomon"], t:"both", av:"king", desc:"David's son who asked for wisdom; temple-builder whose golden age curdled into idolatry through a thousand political marriages." },
  { id:"pharaohs-daughter", name:"Pharaoh's daughter", al:["Pharaoh's daughter","daughter of Pharaoh"], t:"ot", av:"woman", desc:"An unnamed Egyptian princess Solomon marries early in his reign to seal an alliance with Egypt, brought to live in the City of David until his palace, the temple, and Jerusalem's wall are finished (1 Kgs 3:1); later given her own house, since David's former quarters were deemed too holy for her to occupy (1 Kgs 7:8; 9:24) — distinct from any pharaoh named elsewhere in Scripture, whose own identity the text never gives." },
  { id:"two-mothers", name:"The two mothers", al:["two women","two harlots","two prostitutes"], t:"ot", av:"woman", desc:"Two unnamed women sharing a house, each having recently given birth; when one child dies in the night, both claim the surviving baby as her own. Solomon's order to divide the living child with a sword exposes which of the two is the true mother by her willingness to surrender the child rather than see it killed (1 Kgs 3:16-27)." },
  { id:"elijah", name:"Elijah", al:["Elijah","Elias"], t:"both", av:"prophet", desc:"Tishbite in a hair cloak who shut the sky, faced down Baal's prophets on Carmel, and left in a whirlwind of fire." },
  { id:"elisha", name:"Elisha", al:["Elisha"], t:"ot", av:"prophet", desc:"Plowman called by a thrown cloak; double-portion successor of Elijah, worker of homely miracles among ordinary people." },
  { id:"ahab", name:"Ahab", al:["Ahab"], t:"ot", av:"king", desc:"Israel's ivory-palace king, married to Jezebel; brave in battle, weak before his wife, condemned over Naboth's vineyard." },
  { id:"jezebel", name:"Jezebel", al:["Jezebel"], t:"both", av:"woman", desc:"Sidonian princess who made Baal-worship state policy and hunted the LORD's prophets; her name became a byword." },
  { id:"hezekiah", name:"Hezekiah", al:["Hezekiah"], t:"ot", av:"king", desc:"Reformer king who tunneled water into Jerusalem and spread Sennacherib's letter before the LORD — and saw the siege broken." },
  { id:"josiah", name:"Josiah", al:["Josiah"], t:"ot", av:"king", desc:"Boy-king whose workmen found the lost Book of the Law; his reform was Judah's last dawn before Babylon." },
  { id:"isaiah", name:"Isaiah", al:["Isaiah","Esaias"], t:"both", av:"prophet", desc:"Court prophet who saw the LORD high and lifted up; spoke of Immanuel and the suffering Servant." },
  { id:"jeremiah", name:"Jeremiah", al:["Jeremiah"], t:"both", av:"prophet", desc:"The weeping prophet of Anathoth — jailed, dropped in a cistern, vindicated by Jerusalem's fall he had foretold for forty years." },
  { id:"ezekiel", name:"Ezekiel", al:["Ezekiel"], t:"ot", av:"prophet", desc:"Priest-prophet among the canal exiles of Babylon; saw the wheeled throne, the departing glory, and the valley of dry bones." },
  { id:"daniel", name:"Daniel", al:["Daniel"], t:"both", av:"official", desc:"Judean noble made Babylonian sage; unbribable administrator, dream-reader to empires, survivor of the lions' den." },
  { id:"jonah", name:"Jonah", al:["Jonah","Jonas"], t:"both", av:"prophet", desc:"The prophet who sailed the opposite way; three days in the great fish taught him what Nineveh's cattle already knew of mercy." },
  { id:"esther", name:"Esther", al:["Esther","Hadassah"], t:"ot", av:"woman", desc:"Orphan queen of Persia who risked the golden scepter 'for such a time as this.'" },
  { id:"nehemiah", name:"Nehemiah", al:["Nehemiah"], t:"ot", av:"official", desc:"Royal cupbearer turned wall-builder; rebuilt Jerusalem's defenses in fifty-two days with a trowel in one hand and a spear in the other." },
  { id:"ezra", name:"Ezra", al:["Ezra"], t:"ot", av:"priest", desc:"Priest-scribe 'skilled in the Law of Moses' who led exiles home and read the Law to a weeping assembly." },
  { id:"job", name:"Job", al:["Job"], t:"ot", av:"elder", desc:"Blameless man of Uz stripped of everything in a contest he never saw; questioned God from the ash heap and was answered from the whirlwind." },
  { id:"goliath", name:"Goliath", al:["Goliath"], t:"ot", av:"warrior", desc:"Champion of Gath, over nine feet in bronze scale armor, felled by a sling stone in the Elah valley." },
  { id:"uzzah", name:"Uzzah", al:["Uzzah"], t:"ot", av:"warrior", desc:"Son of Abinadab who helped drive the new cart carrying the ark toward Jerusalem; reached out to steady it when the oxen stumbled and was struck dead on the spot for touching what only Levites carrying it by its poles were permitted to touch (2 Sam 6:6-7)." },
  { id:"michal", name:"Michal", al:["Michal"], t:"ot", av:"woman", desc:"Saul's younger daughter, given to David as a wife for a bride-price of a hundred Philistine foreskins; lowered him through a window to save him from her father's assassins and covered his escape with a teraphim decoy (1 Sam 19), was later given to another man during his fugitive years and reclaimed by David once he became king (2 Sam 3:13-16) — then despises his ecstatic dancing before the ark and is left childless for it (2 Sam 6:16-23)." },
  { id:"nathan", name:"Nathan", al:["Nathan"], t:"ot", av:"prophet", desc:"Court prophet under David and Solomon; first approves David's plan to build a temple, then corrects it that same night with the LORD's covenant promise of an everlasting dynasty (2 Sam 7); later confronts David over Bathsheba and Uriah with the parable of the ewe lamb (2 Sam 12), and secures Solomon's succession against Adonijah (1 Kgs 1)." },
  { id:"ishbosheth", name:"Ish-bosheth", al:["Ish-bosheth","Ishbosheth","Esh-baal"], t:"ot", av:"king", desc:"Saul's surviving son, forty years old when Abner installs him as king over Gilead, the Ashurites, Jezreel, Ephraim, Benjamin, and 'all Israel' from Mahanaim while David reigns over Judah alone at Hebron (2 Sam 2:8-10); a figurehead who cannot even rebuke Abner over Rizpah without losing control of his own kingdom (2 Sam 3:7-11), and is assassinated in his bed by two of his own captains once Abner's defection leaves him defenseless (2 Sam 4:5-7)." },
  { id:"rechab", name:"Rechab", al:["Rechab"], t:"ot", av:"warrior", desc:"One of two captains of raiding bands serving Ish-bosheth, a son of Rimmon the Beerothite of Benjamin; with his brother Baanah, murders Ish-bosheth in his bed at noon and carries his head to David at Hebron expecting a reward, only to be executed himself for killing 'a righteous man in his own house on his bed' (2 Sam 4:2-12)." },
  { id:"baanah", name:"Baanah", al:["Baanah"], t:"ot", av:"warrior", desc:"Rechab's brother, the other captain of raiding bands who murders Ish-bosheth in his bed; both brothers are executed by David's order, their hands and feet cut off and their bodies hung by the pool at Hebron (2 Sam 4:2-12)." },
  { id:"mephibosheth", name:"Mephibosheth", al:["Mephibosheth","Merib-baal"], t:"ot", av:"youth", desc:"Jonathan's son, five years old when news of Saul and Jonathan's deaths at Gilboa reached Jezreel; his nurse fled carrying him and dropped him in her hurry, leaving him lame in both feet for life (2 Sam 4:4). David later honors his covenant oath to Jonathan by restoring Saul's land to him and seating him permanently at the king's own table (2 Sam 9)." },
  { id:"abner", name:"Abner", al:["Abner"], t:"ot", av:"warrior", desc:"Saul's cousin and army commander; slept beside the king in camp; props up Ish-bosheth as a rival king over the northern tribes for two years after Saul's death, kills Asahel in self-defense during the standoff at Gibeon's pool (2 Sam 2:18-23), then breaks with Ish-bosheth over Rizpah and defects to David with a promise to bring all Israel to him (2 Sam 3:6-21) — murdered by Joab at Hebron's gate in revenge for Asahel before that promise can be kept." },
  { id:"asahel", name:"Asahel", al:["Asahel"], t:"ot", av:"warrior", desc:"Youngest of Zeruiah's three sons (Joab and Abishai's brother), 'as swift of foot as a wild gazelle' (2 Sam 2:18); chases Abner alone off the battlefield at Gibeon's pool refusing every warning to turn aside, and is killed by a reverse thrust of Abner's spear-butt through the stomach (2 Sam 2:19-23) — the death Joab avenges years later by murdering Abner under a truce (2 Sam 3:27)." },
  { id:"abishai", name:"Abishai", al:["Abishai"], t:"ot", av:"warrior", desc:"Middle son of Zeruiah, Joab's brother and Asahel's (2 Sam 2:18); joins the pursuit of Abner after Asahel's death and, per David's later words, shares the blood-guilt of Abner's murder alongside Joab (2 Sam 3:30) — one of David's fiercest and most loyal commanders across the reign, from the raid on Saul's camp (1 Sam 26:6-9) to the rescue of David himself from a giant at Gob (2 Sam 21:15-17)." },
  { id:"bathsheba", name:"Bathsheba", al:["Bathsheba"], t:"ot", av:"woman", desc:"Daughter of Eliam and wife of Uriah the Hittite; summoned to David's palace and made pregnant while her husband was away at the siege of Rabbah, then taken as David's wife after Uriah's engineered death (2 Sam 11). The son of that union dies in infancy, but she bears David a second son, Solomon, whom the LORD loves (2 Sam 12:24) — and later secures his succession over Adonijah (1 Kgs 1)." },
  { id:"uriah", name:"Uriah the Hittite", al:["Uriah","Uriah the Hittite"], t:"ot", av:"warrior", desc:"One of David's Thirty mighty men (2 Sam 23:39), a Hittite by descent but a loyal soldier of Israel; refuses the comfort of his own house and wife while the ark and his comrades remain camped in the open field, so David has Joab place him where the fighting is fiercest and pull back the support around him, engineering his death at the siege of Rabbah (2 Sam 11)." },
  { id:"joab", name:"Joab", al:["Joab"], t:"ot", av:"warrior", desc:"David's nephew (son of Zeruiah) and army commander for most of the reign — found the water shaft that won Jerusalem (2 Sam 5:8), later murdered Abner under a truce and Absalom against direct orders. Carries out David's letter ordering Uriah exposed and abandoned at the front of the siege of Rabbah without asking why (2 Sam 11:14-17), then deliberately holds back the final assault on the city so David can arrive and take the credit — and the crown — for its capture (2 Sam 12:26-29)." },
  { id:"absalom", name:"Absalom", al:["Absalom"], t:"ot", av:"warrior", desc:"David's third son, famous for his looks and his heavy hair; avenged his sister Tamar's rape by killing his half-brother Amnon, fled to his grandfather's court at Geshur for three years, then spent years back in Jerusalem unreconciled with his father before openly courting Israel's loyalty at the city gate and launching a coup from Hebron (2 Sam 13-15). Killed by Joab in the forest of Ephraim against David's explicit order to deal gently with him, his death draws out the rawest grief of David's life: 'O Absalom, my son, my son!' (2 Sam 18:33)." },
  { id:"ahithophel", name:"Ahithophel", al:["Ahithophel"], t:"ot", av:"elder", desc:"David's trusted counselor from Giloh, whose advice 'was as if one consulted the word of God' (2 Sam 16:23); defects to Absalom's rebellion — possibly because his granddaughter was Bathsheba (2 Sam 11:3; 23:34) — and gives ruthlessly effective counsel that Hushai must scramble to undo. When Absalom follows Hushai's advice instead, Ahithophel goes home and hangs himself (2 Sam 17:23)." },
  { id:"hushai", name:"Hushai the Archite", al:["Hushai"], t:"ot", av:"elder", desc:"David's friend and counselor who meets the fleeing king in mourning dress on the Mount of Olives, then agrees to return to Jerusalem as a planted double agent — feigning loyalty to Absalom in order to counter Ahithophel's counsel and buy David time to escape across the Jordan (2 Sam 15:32-37; 17:5-14)." },
  { id:"ittai", name:"Ittai the Gittite", al:["Ittai"], t:"ot", av:"warrior", desc:"A foreign commander from Gath, only recently arrived in David's service with 600 men, who refuses David's offer to sit out the rebellion and stay loyal to the new regime: 'wherever my lord the king shall be... there also will your servant be' (2 Sam 15:19-22). David later trusts him with command of a third of the army against Absalom (2 Sam 18:2)." },
  { id:"zadok", name:"Zadok", al:["Zadok"], t:"ot", av:"priest", desc:"Priest who carries the ark out of Jerusalem with David during Absalom's revolt, but is sent back at the king's order to keep it in the city and serve as an intelligence conduit through his son Ahimaaz (2 Sam 15:24-29); later anoints Solomon king (1 Kgs 1:39), founding the priestly line that bears his name." },
  { id:"abiathar", name:"Abiathar", al:["Abiathar"], t:"ot", av:"priest", desc:"Sole survivor of the priests of Nob massacred by Saul (1 Sam 22:20-23), who has served David as priest ever since; carries the ark out of Jerusalem alongside Zadok during Absalom's revolt and is sent back with him to relay intelligence through his son Jonathan (2 Sam 15:24-29). Later backs the wrong claimant to David's throne and is deposed by Solomon (1 Kgs 2:26-27)." },
  { id:"ahimaaz", name:"Ahimaaz", al:["Ahimaaz"], t:"ot", av:"youth", desc:"Zadok's son, used with Jonathan son of Abiathar as a fast-running messenger relay between Jerusalem and David during Absalom's revolt (2 Sam 15:27-28; 17:17-21); begs Joab to let him carry news of the battle's outcome, outruns the Cushite by way of the plain, but cannot bring himself to plainly tell David that Absalom is dead (2 Sam 18:19-30)." },
  { id:"shimei", name:"Shimei son of Gera", al:["Shimei"], t:"ot", av:"elder", desc:"A Benjaminite of Saul's own clan, from Bahurim, who runs along the ridge above the fleeing David's column throwing stones and dust and cursing him as a 'man of blood' who stole Saul's throne (2 Sam 16:5-13); when Abishai asks leave to take off his head, David restrains him — 'let him curse... it may be that the LORD will look on my affliction.' Begs David's pardon on his return in 2 Sam 19:16-23 and is spared by royal oath, but David's deathbed charge to Solomon marks him as unfinished business, and Solomon has him executed in 1 Kgs 2:36-46 once he breaks the terms of his own parole." },
  { id:"barzillai", name:"Barzillai the Gileadite", al:["Barzillai"], t:"ot", av:"elder", desc:"A very wealthy old man from Rogelim in Gilead who, with Shobi son of Nahash and Machir son of Ammiel, brings bedding, basins, pottery, grain, and food to David's exhausted company at Mahanaim (2 Sam 17:27-29). When David returns across the Jordan, the eighty-year-old Barzillai escorts him partway but declines an invitation to the palace as too old to enjoy it, asking only that his blessing be shown instead to his son Chimham (2 Sam 19:31-40)." },
  { id:"cushite-messenger", name:"The Cushite messenger", al:["Cushite","the Cushite"], t:"ot", av:"traveler", desc:"An unnamed foreign courier — from Cush (Nubia, along the upper Nile) or serving in that royal messenger role — whom Joab sends to report the battle's outcome and Absalom's death plainly, after refusing to let Ahimaaz carry news he judged too dangerous to deliver (2 Sam 18:21-32)." },
  { id:"gad", name:"Gad", al:["Gad"], t:"ot", av:"prophet", desc:"'David's seer' (2 Sam 24:11), first appearing early in David's fugitive years to tell him to leave the stronghold for the land of Judah (1 Sam 22:5); decades later delivers the census judgment's three-option choice of famine, flight, or plague, then instructs him to build the altar at Araunah's threshing floor (2 Sam 24:11-19)." },
  { id:"araunah", name:"Araunah", al:["Araunah","Ornan"], t:"ot", av:"elder", desc:"A Jebusite — one of Jerusalem's pre-conquest inhabitants — who owns the threshing floor on the hill north of the city where the plague-bearing angel's advance is stayed; offers David the floor, oxen, and threshing sledges free of charge, but David insists on paying full price rather than offer 'burnt offerings... that cost me nothing' (2 Sam 24:18-24; called Ornan in 1 Chron 21)." },
  { id:"hadadezer", name:"Hadadezer", al:["Hadadezer","Hadarezer"], t:"ot", av:"king", desc:"Son of Rehob, king of Aram-Zobah, defeated by David while marching to restore his power at the Euphrates; loses 1,700 horsemen and 20,000 foot soldiers and his officers' gold shields, and Aram-Damascus's attempt to rescue him only adds another 22,000 Aramean dead to the defeat (2 Sam 8:3-8; the parallel account in 1 Chron 18:3-8 gives different troop totals)." },
  { id:"jehoshaphat-recorder", name:"Jehoshaphat (the recorder)", al:["Jehoshaphat"], t:"ot", av:"official", desc:"Son of Ahilud, David's 'recorder' (mazkir) — the court official who kept royal records and likely managed the king's public affairs and ceremony; named in both of David's cabinet lists (2 Sam 8:16; 20:24) and again under Solomon (1 Kgs 4:3)." },
  { id:"seraiah-scribe", name:"Seraiah (the scribe)", al:["Seraiah","Sheva","Shisha"], t:"ot", av:"official", desc:"David's secretary/scribe, responsible for the court's correspondence and documents; named Seraiah here (2 Sam 8:17), Sheva in 2 Sam 20:25, and Shisha in 1 Kings 4:3 — the same office under three slightly different name-spellings across the record." },
  { id:"benaiah", name:"Benaiah", al:["Benaiah"], t:"ot", av:"warrior", desc:"Son of Jehoiada, commander over David's foreign mercenary guard, the Cherethites and Pelethites (2 Sam 8:18); one of the Thirty's most storied fighters, credited with killing two of Moab's champions, a lion in a pit on a snowy day, and a huge Egyptian he disarmed with the man's own spear (2 Sam 23:20-23). Later backs Solomon over Adonijah and executes Joab in his own turn (1 Kgs 1-2)." },
  { id:"cherethites-pelethites", name:"Cherethites and Pelethites", al:["Cherethites","Pelethites"], t:"ot", av:"warrior", desc:"David's personal foreign mercenary guard, likely of Aegean/Philistine origin (the Cherethites are linked to Crete), commanded by Benaiah and answerable to the king alone rather than to Israel's tribal levies (2 Sam 8:18); they stay loyal through Absalom's revolt (2 Sam 15:18) and secure Solomon's coronation over Adonijah's rival claim (1 Kgs 1:38-40)." },
  { id:"ziba", name:"Ziba", al:["Ziba"], t:"ot", av:"official", desc:"A servant of Saul's household, summoned by David to locate any survivor of Saul's line worth honoring for Jonathan's sake; directs him to Mephibosheth at Lo-debar and is put in charge — with his own fifteen sons and twenty servants — of working Saul's restored land for him (2 Sam 9:2-12). Later meets the fleeing David during Absalom's revolt with supplies and a slander against Mephibosheth, and is provisionally granted all his master's land; when Mephibosheth's own account contradicts him after the revolt, David splits the estate between them without ruling on who told the truth (2 Sam 16:1-4; 19:24-30)." },
  { id:"hanun", name:"Hanun", al:["Hanun"], t:"ot", av:"king", desc:"Son and successor of Nahash, king of the Ammonites; persuaded by his princes that David's envoys of condolence are spies, he shaves off half the beard of each man and cuts their garments off at the hips before sending them home in disgrace — an insult that starts the war against David's coalition of Ammon and hired Aramean mercenaries and ends, two chapters later, with Rabbah besieged, captured, and Hanun's own gold crown taken for David's head (2 Sam 10:1-19; 12:26-31)." },
  { id:"nahash", name:"Nahash", al:["Nahash"], t:"ot", av:"king", desc:"King of the Ammonites whose death opens 2 Samuel 10 and whose son Hanun succeeds him; David sends comforters 'for his father dealt loyally with me' (2 Sam 10:2), an unspecified past kindness some link to this same Nahash's earlier hostility toward Saul — the very king who threatened to gouge out the right eye of every man of Jabesh-gilead before Saul's rescue made him king (1 Sam 11:1-2) — on the old principle that Saul's enemies were David's natural friends during his fugitive years." },
  { id:"shobach", name:"Shobach", al:["Shobach","Shophach"], t:"ot", av:"warrior", desc:"Commander of Hadadezer's army, brought up to lead the Aramean reinforcements 'from beyond the Euphrates' after Joab and Abishai's first victory over the Ammonite coalition; David personally crosses the Jordan to meet this second Aramean army at Helam, where Shobach is wounded and dies, ending Aram's willingness to keep fighting on Ammon's behalf (2 Sam 10:15-18; called Shophach in the parallel account, 1 Chron 19:16-18)." },
  { id:"tamar-david", name:"Tamar (David's daughter)", al:["Tamar"], t:"ot", av:"woman", desc:"David's beautiful daughter and Absalom's full sister, raped by her half-brother Amnon after he lures her to his house on a pretext of illness; left 'a desolate woman' in Absalom's house afterward, her ruined ornamented robe (the mark of a king's virgin daughter) torn and ashes on her head (2 Sam 13:1-20). Absalom later names his own daughter Tamar after her (2 Sam 14:27)." },
  { id:"amnon", name:"Amnon", al:["Amnon"], t:"ot", av:"youth", desc:"David's firstborn son and heir apparent; feigns illness on his cousin Jonadab's advice to lure his half-sister Tamar to his house alone, then rapes her and immediately hates her more than he had ever loved her (2 Sam 13:1-19). Killed two years later on Absalom's order at a sheepshearing feast in revenge — the first of the sons Nathan's oracle said the sword would claim from David's own house (2 Sam 13:23-29; 12:10-11)." },
  { id:"jonadab", name:"Jonadab", al:["Jonadab"], t:"ot", av:"official", desc:"Son of David's brother Shimeah and 'a very shrewd man'; devises the ruse that lets Amnon get Tamar alone (2 Sam 13:3-5), then, once news of a massacre reaches David, is the only one calm enough to correctly guess that only Amnon — not all the king's sons — is actually dead, since he already knew Absalom's plan (2 Sam 13:32-35)." },
  { id:"wise-woman-tekoa", name:"The wise woman of Tekoa", al:["wise woman of Tekoa","wise woman"], t:"ot", av:"woman", desc:"A skilled speaker Joab recruits and coaches to pose as a grieving widow before David, drawing him with a fictional case of two sons — one dead, one facing the family's demand for blood vengeance — into unknowingly ruling in favor of his own banished son Absalom's return (2 Sam 14:1-20)." },
  { id:"talmai", name:"Talmai (king of Geshur)", al:["Talmai"], t:"ot", av:"king", desc:"King of the small Aramean kingdom of Geshur, and (through his daughter Maacah, one of David's wives) Absalom's own maternal grandfather; Absalom flees to his court for three years after murdering Amnon, safe on the strength of family standing on both sides of the border (2 Sam 13:37-38; 3:3)." },
  { id:"amasa", name:"Amasa", al:["Amasa"], t:"ot", av:"warrior", desc:"David's nephew (son of his sister Abigail) who commanded Absalom's rebel army; once the revolt collapses, David offers him Joab's job outright — 'you are my bone and my flesh... you shall be commander of my army from now on' (2 Sam 19:13). Slow to muster Judah's forces against Sheba's revolt, he is greeted by Joab at the great stone in Gibeon with a kiss and a hidden sword driven into his stomach, and Joab simply resumes command over the men left standing around his body (2 Sam 20:4-13)." },
  { id:"sheba-bichri", name:"Sheba son of Bichri", al:["Sheba"], t:"ot", av:"warrior", desc:"A Benjaminite 'worthless man' (2 Sam 20:1) who blows the trumpet and pulls all Israel away from David the moment the Absalom crisis ends — 'we have no share in David... every man to his tents, O Israel!' Pursued by Joab the length of the land, he is besieged at Abel Beth-maacah until the town's wise woman ends the standoff by having his head thrown over the wall (2 Sam 20:1-22)." },
  { id:"wise-woman-abel", name:"The wise woman of Abel", al:["wise woman of Abel","wise woman"], t:"ot", av:"woman", desc:"An unnamed negotiator who calls out to Joab from the wall of besieged Abel Beth-maacah, invokes the town's old reputation as a place people 'used to ask counsel,' and talks him out of destroying 'a mother in Israel' by persuading the citizens to throw Sheba son of Bichri's head over the wall instead, ending the siege without another death (2 Sam 20:16-22)." },
  { id:"rizpah", name:"Rizpah", al:["Rizpah"], t:"ot", av:"woman", desc:"Saul's concubine, mother of two of the seven descendants of Saul David hands over to the Gibeonites for execution over Saul's broken treaty; spreads sackcloth on the rock at Gibeah and keeps a months-long vigil driving off birds and beasts from the exposed bodies until David, hearing of it, finally has Saul and Jonathan's bones — and the executed men's — properly reburied at Zela (2 Sam 21:8-14). Abner's alleged relationship with her is also what triggers his break with Ish-bosheth (2 Sam 3:7)." },
  { id:"gibeonites", name:"The Gibeonites", al:["Gibeonites","Gibeonite"], t:"ot", av:"elder", desc:"Survivors of the Hivite league who tricked Joshua into a peace treaty by feigning distant origin (Josh 9); centuries later Saul, 'in his zeal for Israel and Judah,' broke that sworn treaty by trying to wipe them out, bringing a three-year famine on David's Israel that David can only end by handing over seven of Saul's descendants for execution at their demand (2 Sam 21:1-9)." },
  { id:"philistine-giants", name:"The four Philistine giants", al:["Ishbi-benob","Saph","the giant of Gath"], t:"ot", av:"warrior", desc:"Four 'descendants of Rapha' from Gath, fought in a string of border battles late in David's reign: Ishbi-benob, whose new bronze-tipped spear nearly kills an exhausted David until Abishai steps in (vv. 15-17); Saph, killed by Sibbecai at Gob; Goliath's brother (Lahmi in 1 Chron 20:5, unnamed here) killed by Elhanan; and an unnamed giant with six fingers on each hand and six toes on each foot, killed at Gath by Jonathan, David's nephew (2 Sam 21:15-22)." },
  { id:"elhanan", name:"Elhanan", al:["Elhanan"], t:"ot", av:"warrior", desc:"Son of Jaare-oregim (Jair in 1 Chron 20:5) from Bethlehem, one of David's fighting men who kills 'the brother of Goliath the Gittite' at Gob, whose spear shaft was 'like a weaver's beam' (2 Sam 21:19) — the same phrase used of Goliath's own spear (1 Sam 17:7), and the verse behind the standard harmonization that 1 Chronicles 20:5 preserves the more original wording, naming his victim as Lahmi, Goliath's brother, rather than Goliath himself." },
  { id:"josheb-basshebeth", name:"Josheb-basshebeth", al:["Josheb-basshebeth","Adino the Eznite","Jashobeam"], t:"ot", av:"warrior", desc:"A Tahkemonite, chief of David's Three — the innermost rank of the mighty men — credited with raising his spear against eight hundred men and killing them in a single encounter, also called Adino the Eznite (2 Sam 23:8; the parallel 1 Chron 11:11 names him Jashobeam and gives the number as three hundred, one of several small textual variants between the two rosters)." },
  { id:"eleazar-dodo", name:"Eleazar son of Dodo", al:["Eleazar"], t:"ot", av:"warrior", desc:"An Ahohite, one of the Three, who stood his ground beside David at Pas-dammim when the rest of Israel's line broke before the massed Philistines — struck down the enemy until his hand froze fast to his sword, and the LORD won a great victory that day; the troops returned only in time to strip the dead (2 Sam 23:9-10)." },
  { id:"shammah-agee", name:"Shammah son of Agee", al:["Shammah"], t:"ot", av:"warrior", desc:"A Hararite, the third of the Three, who single-handedly held a field full of lentils against a Philistine raiding party after the rest of Israel's troops fled it — 'the LORD brought about a great victory' through him alone (2 Sam 23:11-12); one of several men named Shammah in David's story, distinct from David's older brother of the same name (1 Sam 16:9)." },

  // ---- New Testament ----
  { id:"jesus", name:"Jesus", al:["Jesus","Christ","Jesus Christ","the Son of Man"], t:"nt", av:"prophet", desc:"Jesus of Nazareth, the Christ — carpenter's son from Galilee whose teaching, healings, crucifixion under Pontius Pilate and resurrection are the center of the New Testament." },
  { id:"mary", name:"Mary (mother of Jesus)", al:["Mary"], t:"nt", av:"woman", desc:"Galilean girl of Nazareth who said 'let it be to me according to your word'; treasured what she could not yet understand." },
  { id:"joseph-nt", name:"Joseph (of Nazareth)", al:["Joseph"], t:"nt", av:"traveler", desc:"Carpenter of Nazareth, 'a just man,' who guarded mother and child through census journey, flight to Egypt, and quiet years." },
  { id:"john-baptist", name:"John the Baptist", al:["John the Baptist"], t:"nt", av:"prophet", desc:"Camel-hair prophet of the Jordan wilderness, on locusts and wild honey; voice crying 'Prepare the way.'" },
  { id:"peter", name:"Peter", al:["Peter","Simon Peter","Cephas","Simon"], t:"nt", av:"fisherman", desc:"Galilean fisherman, first to confess and first to deny; restored over breakfast coals to feed the flock." },
  { id:"andrew", name:"Andrew", al:["Andrew"], t:"nt", av:"fisherman", desc:"Peter's brother, always bringing someone to Jesus — his brother, a boy with loaves, Greeks at the feast." },
  { id:"james-zebedee", name:"James (son of Zebedee)", al:["James"], t:"nt", av:"fisherman", desc:"One of the 'sons of thunder'; of the inner three; first apostle to die for the name (Acts 12:2)." },
  { id:"john-apostle", name:"John (the apostle)", al:["John"], t:"nt", av:"fisherman", desc:"The disciple Jesus loved — fisherman, eyewitness, elder of Ephesus, seer of Patmos." },
  { id:"matthew", name:"Matthew", al:["Matthew","Levi"], t:"nt", av:"official", desc:"Tax collector at the Capernaum customs post who left the booth mid-shift and threw Jesus a banquet of misfits." },
  { id:"thomas", name:"Thomas", al:["Thomas","Didymus"], t:"nt", av:"traveler", desc:"The twin who demanded to touch the wounds — and then made the highest confession: 'My Lord and my God.'" },
  { id:"judas", name:"Judas Iscariot", al:["Judas Iscariot","Judas"], t:"nt", av:"traveler", desc:"Keeper of the moneybag who sold his teacher for a slave's price and could not live with the receipt." },
  { id:"mary-magdalene", name:"Mary Magdalene", al:["Mary Magdalene","Magdalene"], t:"nt", av:"woman", desc:"Freed from seven demons; funded the ministry; first witness of the resurrection, sent to tell the others." },
  { id:"martha", name:"Martha", al:["Martha"], t:"nt", av:"woman", desc:"Bethany's brisk householder — distracted by much serving, yet author of a confession to match Peter's (John 11:27)." },
  { id:"lazarus", name:"Lazarus", al:["Lazarus"], t:"nt", av:"traveler", desc:"Jesus' friend at Bethany, four days dead, called out of the tomb still wrapped in graveclothes." },
  { id:"nicodemus", name:"Nicodemus", al:["Nicodemus"], t:"nt", av:"elder", desc:"Pharisee and ruler who came by night with questions; returned in daylight with seventy-five pounds of burial spices." },
  { id:"samaritan-woman", name:"The Samaritan woman", al:["woman of Samaria"], t:"nt", av:"woman", desc:"Came to Jacob's well at noon to avoid the crowd; left her jar behind and evangelized the town that shunned her." },
  { id:"pilate", name:"Pontius Pilate", al:["Pilate","Pontius Pilate"], t:"nt", av:"official", desc:"Roman prefect of Judea (AD 26–36) who found no guilt, washed his hands, and signed the order anyway." },
  { id:"herod-great", name:"Herod the Great", al:["Herod"], t:"nt", av:"king", desc:"Rome's client 'King of the Jews' (r. 37–4 BC): master builder of the temple platform and Caesarea, paranoid killer of rivals — and of Bethlehem's infants. (Later 'Herods' in the NT are his sons and grandson.)" },
  { id:"caiaphas", name:"Caiaphas", al:["Caiaphas"], t:"nt", av:"priest", desc:"High priest (AD 18–36) who calculated that one man should die for the people." },
  { id:"stephen", name:"Stephen", al:["Stephen"], t:"nt", av:"youth", desc:"Table-server full of grace and power; his speech retold Israel's story and his death, witnessed by Saul of Tarsus, scattered the seed." },
  { id:"philip-evangelist", name:"Philip the evangelist", al:["Philip"], t:"nt", av:"traveler", desc:"Scattered from Jerusalem, he preached in Samaria and explained Isaiah in a moving chariot to an Ethiopian official." },
  { id:"paul", name:"Paul", al:["Paul","Saul of Tarsus"], t:"nt", av:"traveler", desc:"Pharisee of Tarsus, persecutor turned apostle on the Damascus road; tentmaker, church planter across the Aegean world, letter-writer, prisoner of Rome." },
  { id:"barnabas", name:"Barnabas", al:["Barnabas"], t:"nt", av:"elder", desc:"'Son of encouragement' from Cyprus — vouched for the ex-persecutor and gave John Mark a second chance." },
  { id:"silas", name:"Silas", al:["Silas","Silvanus"], t:"nt", av:"traveler", desc:"Prophet and Roman citizen who sang at midnight in the Philippian stocks beside Paul." },
  { id:"timothy", name:"Timothy", al:["Timothy","Timotheus"], t:"nt", av:"youth", desc:"Paul's 'true child in the faith' from Lystra; timid stomach, tested worth, entrusted with Ephesus." },
  { id:"lydia", name:"Lydia", al:["Lydia"], t:"nt", av:"woman", desc:"Purple-cloth merchant of Thyatira, first convert of Europe, whose opened heart opened her house." },
  { id:"aquila-priscilla", name:"Aquila & Priscilla", al:["Aquila","Priscilla","Prisca"], t:"nt", av:"traveler", desc:"Tentmaking couple expelled from Rome; hosted churches in three cities and privately tuned up Apollos' theology." },
  { id:"apollos", name:"Apollos", al:["Apollos"], t:"nt", av:"official", desc:"Eloquent Alexandrian, mighty in the Scriptures, who watered where Paul planted." },
  { id:"luke", name:"Luke", al:["Luke"], t:"nt", av:"official", desc:"'The beloved physician' — historian of the Gospel and Acts, eyewitness of the 'we' voyages including the great shipwreck." },
  { id:"cornelius", name:"Cornelius", al:["Cornelius"], t:"nt", av:"warrior", desc:"Centurion of the Italian Cohort at Caesarea; his vision and Peter's met in the middle, and the Spirit fell on Gentiles." },
  { id:"felix", name:"Felix", al:["Felix"], t:"nt", av:"official", desc:"Procurator who trembled at Paul's reasoning but hoped for a bribe; left him in prison as a favor." },
  { id:"festus", name:"Festus", al:["Festus"], t:"nt", av:"official", desc:"Felix's successor, before whom Paul appealed: 'To Caesar you shall go.'" },
  { id:"agrippa", name:"Agrippa", al:["Agrippa"], t:"nt", av:"king", desc:"Herod Agrippa II, last of the dynasty, almost persuaded — 'This man could have been set free.'" },
  { id:"julius", name:"Julius the centurion", al:["Julius"], t:"nt", av:"warrior", desc:"Centurion of the Augustan Cohort escorting Paul to Rome; trusted the pilot over the prisoner until the storm taught him otherwise (Acts 27)." },
  { id:"publius", name:"Publius", al:["Publius"], t:"nt", av:"official", desc:"'First man' of Malta whose father Paul healed after the shipwreck." },
  { id:"lot", name:"Lot", al:["Lot"], t:"ot", av:"elder", desc:"Abram's nephew who chose the well-watered Jordan plain, settled in Sodom, was rescued twice — once from kings, once from fire — and ended in a cave with his two daughters." },
  { id:"hagar", name:"Hagar", al:["Hagar"], t:"ot", av:"woman", desc:"Sarai's Egyptian servant, given to Abram to bear an heir; fled to the desert and became the first person in Scripture to name God, then was sent away with her son." },
  { id:"ishmael", name:"Ishmael", al:["Ishmael"], t:"ot", av:"youth", desc:"Abram's son by Hagar, born when Abram was 86; circumcised with his father's household and promised a nation of his own, though not the covenant line." },
  { id:"abimelech", name:"Abimelech of Gerar", al:["Abimelech"], t:"ot", av:"king", desc:"Philistine king of Gerar who took Sarah (and later Rebekah) for his own household by mistake, then made covenants with both Abraham and Isaac over disputed wells." },
  { id:"phicol", name:"Phicol", al:["Phicol"], t:"ot", av:"warrior", desc:"Commander of Abimelech's army, present at the well-covenants both Abraham and Isaac struck with the king of Gerar." },
  { id:"rebekah", name:"Rebekah", al:["Rebekah","Rebecca"], t:"ot", av:"woman", desc:"Bethuel's daughter, drawn water for Eliezer's camels at a Haran well, became Isaac's wife, and later schemed to secure Jacob's stolen blessing." },
  { id:"bethuel", name:"Bethuel", al:["Bethuel"], t:"ot", av:"elder", desc:"Son of Nahor and Milcah, father of Rebekah and Laban, living in Aram-naharaim near Haran." },
  { id:"laban", name:"Laban", al:["Laban"], t:"ot", av:"elder", desc:"Rebekah's brother, first met hurrying out to welcome Eliezer's gifts at the family well; later Jacob's uncle and father-in-law." },
  { id:"milcah", name:"Milcah", al:["Milcah"], t:"ot", av:"woman", desc:"Wife of Abraham's brother Nahor, grandmother of Rebekah through their son Bethuel." },
  { id:"keturah", name:"Keturah", al:["Keturah"], t:"ot", av:"woman", desc:"Wife Abraham took after Sarah's death, bearing him six more sons who were sent east with gifts, away from Isaac." },
  { id:"esau", name:"Esau", al:["Esau"], t:"ot", av:"shepherd", desc:"Isaac and Rebekah's firstborn twin, a skilled hunter who sold his birthright for stew and was later tricked out of his father's blessing." },
  { id:"ishmaels-sons", name:"Ishmael's twelve sons", al:["Nebaioth","Kedar","Adbeel","Mibsam"], t:"ot", av:"elder", desc:"Twelve tribal princes born to Ishmael, fulfilling God's promise that he would father a great nation of his own (Gen 25:12-16)." },
  { id:"melchizedek", name:"Melchizedek", al:["Melchizedek"], t:"ot", av:"priest", desc:"King of Salem and 'priest of God Most High' who blessed Abram with bread and wine after the battle of the kings and received a tithe from him." },
  { id:"eliezer", name:"Eliezer of Damascus", al:["Eliezer"], t:"ot", av:"official", desc:"Abram's chief household servant, named as his likely heir before Isaac's birth was promised." },
  { id:"chedorlaomer", name:"Chedorlaomer and the kings", al:["Chedorlaomer","Amraphel","Arioch","Tidal"], t:"ot", av:"king", desc:"The Elamite king who led a four-king coalition against five rebelling Canaanite kings (including Sodom and Gomorrah), captured Lot, and was defeated by Abram's night raid." },
  { id:"lots-wife", name:"Lot's wife", al:["Lot's wife"], t:"ot", av:"woman", desc:"Fled Sodom with her family but looked back against the angels' warning and became a pillar of salt." },
  { id:"lots-daughters", name:"Lot's daughters", al:["Lot's daughters"], t:"ot", av:"woman", desc:"Escaped Sodom's destruction with their father and, fearing no husbands remained, schemed to preserve his line — becoming ancestresses of Moab and Ammon." },
  { id:"rachel", name:"Rachel", al:["Rachel"], t:"ot", av:"woman", desc:"Laban's younger daughter, met at the well and loved by Jacob at first sight; long barren, then mother of Joseph and Benjamin, dying in childbirth near Bethlehem." },
  { id:"leah", name:"Leah", al:["Leah"], t:"ot", av:"woman", desc:"Laban's elder daughter, given to Jacob by a wedding-night trick in Rachel's place; unloved but fruitful, mother of six sons and a daughter." },
  { id:"bilhah", name:"Bilhah", al:["Bilhah"], t:"ot", av:"woman", desc:"Rachel's maidservant, given to Jacob to bear children on Rachel's behalf, mother of Dan and Naphtali." },
  { id:"zilpah", name:"Zilpah", al:["Zilpah"], t:"ot", av:"woman", desc:"Leah's maidservant, given to Jacob to bear children on Leah's behalf, mother of Gad and Asher." },
  { id:"reuben", name:"Reuben", al:["Reuben"], t:"ot", av:"youth", desc:"Jacob and Leah's firstborn, who later slept with his father's concubine Bilhah and forfeited his birthright rank (Gen 35:22; 49:3-4)." },
  { id:"simeon", name:"Simeon", al:["Simeon"], t:"ot", av:"youth", desc:"Jacob and Leah's second son, who with Levi avenged Dinah by slaughtering the men of Shechem (Gen 34:25-26)." },
  { id:"levi", name:"Levi", al:["Levi"], t:"ot", av:"youth", desc:"Jacob and Leah's third son, partner with Simeon in the Shechem massacre; his own line later becomes Israel's priestly tribe." },
  { id:"judah", name:"Judah", al:["Judah"], t:"ot", av:"youth", desc:"Jacob and Leah's fourth son, ancestor of Israel's royal line and eventually the Messiah." },
  { id:"dan", name:"Dan", al:["Dan"], t:"ot", av:"youth", desc:"Jacob's fifth son, born to Rachel's maid Bilhah; his name ('he has judged') marks Rachel's answered plea." },
  { id:"naphtali", name:"Naphtali", al:["Naphtali"], t:"ot", av:"youth", desc:"Jacob's sixth son, Bilhah's second, born amid Rachel and Leah's rivalry over Jacob." },
  { id:"gad-son-jacob", name:"Gad (son of Jacob)", al:["Gad"], t:"ot", av:"youth", desc:"Jacob's seventh son, born to Leah's maid Zilpah after Leah stopped bearing children herself." },
  { id:"asher", name:"Asher", al:["Asher"], t:"ot", av:"youth", desc:"Jacob's eighth son, Zilpah's second, named for the happiness his birth brought Leah." },
  { id:"issachar", name:"Issachar", al:["Issachar"], t:"ot", av:"youth", desc:"Jacob's ninth son, born to Leah after she traded her son's mandrakes to Rachel for a night with Jacob." },
  { id:"zebulun", name:"Zebulun", al:["Zebulun"], t:"ot", av:"youth", desc:"Jacob and Leah's sixth and final son together, born after Leah declares Jacob will now honor her." },
  { id:"benjamin", name:"Benjamin", al:["Benjamin","Ben-oni"], t:"ot", av:"youth", desc:"Jacob and Rachel's second son, named 'son of sorrow' by his dying mother and renamed 'son of the right hand' by Jacob (Gen 35:16-19)." },
  { id:"dinah", name:"Dinah", al:["Dinah"], t:"ot", av:"woman", desc:"Jacob and Leah's daughter, violated by Shechem the Hivite prince, an act her brothers Simeon and Levi avenged with a massacre (Gen 34)." },
  { id:"shechem-prince", name:"Shechem (prince of the Hivites)", al:["Shechem"], t:"ot", av:"elder", desc:"Hamor's son who seized and violated Dinah, then genuinely sought to marry her — and was killed with his father and city by Simeon and Levi (Gen 34)." },
  { id:"hamor", name:"Hamor", al:["Hamor"], t:"ot", av:"elder", desc:"Hivite ruler of Shechem, father of the prince who violated Dinah; negotiated intermarriage and land-sharing with Jacob's sons before their deception cost his city everything (Gen 34)." },
  { id:"tamar-judah", name:"Tamar (Judah's daughter-in-law)", al:["Tamar"], t:"ot", av:"woman", desc:"Widow of Er and Onan who, denied Shelah as promised, posed as a shrine prostitute to secure an heir through Judah himself, bearing Perez and Zerah (Gen 38)." },
  { id:"er", name:"Er", al:["Er"], t:"ot", av:"youth", desc:"Judah's firstborn by Shua's daughter, 'wicked in the LORD's sight,' struck dead before fathering children (Gen 38:6-7)." },
  { id:"onan", name:"Onan", al:["Onan"], t:"ot", av:"youth", desc:"Judah's second son, struck dead for refusing to raise up an heir for his dead brother Er through Tamar (Gen 38:8-10)." },
  { id:"shelah", name:"Shelah", al:["Shelah"], t:"ot", av:"youth", desc:"Judah's third son by Shua's daughter, withheld from Tamar out of Judah's fear he too would die (Gen 38:11, 14, 26)." },
  { id:"potiphar", name:"Potiphar", al:["Potiphar"], t:"ot", av:"official", desc:"Pharaoh's captain of the guard who bought Joseph as a slave, made him overseer of his house, then imprisoned him on his wife's false accusation (Gen 39)." },
  { id:"potiphars-wife", name:"Potiphar's wife", al:["Potiphar's wife"], t:"ot", av:"woman", desc:"Repeatedly propositioned Joseph, then falsely accused him of assault when he fled, using his garment as false evidence (Gen 39:7-18)." },
  { id:"cupbearer", name:"Pharaoh's cupbearer", al:["cupbearer","chief butler"], t:"ot", av:"official", desc:"Imprisoned with Joseph, dreamed of a vine and cup restored to Pharaoh's hand, and was reinstated as Joseph interpreted — but forgot Joseph for two years (Gen 40; 41:9-13)." },
  { id:"baker", name:"Pharaoh's baker", al:["baker","chief baker"], t:"ot", av:"official", desc:"Imprisoned with Joseph, dreamed of birds eating bread from baskets on his head, and was hanged as Joseph interpreted (Gen 40)." },
  { id:"pharaoh-joseph", name:"Pharaoh (Joseph's era)", al:["Pharaoh"], t:"ot", av:"king", desc:"Egypt's king whose two dreams of cattle and grain Joseph interpreted, elevating Joseph to vizier over all Egypt during seven years of famine (Gen 41; 45; 47)." },
  { id:"asenath", name:"Asenath", al:["Asenath"], t:"ot", av:"woman", desc:"Daughter of Potiphera, priest of On, given to Joseph as wife by Pharaoh; mother of Manasseh and Ephraim (Gen 41:45, 50-52)." },
  { id:"potiphera", name:"Potiphera", al:["Potiphera","Poti-phera"], t:"ot", av:"priest", desc:"Priest of On (Heliopolis) whose daughter Asenath was given to Joseph in marriage (Gen 41:45)." },
  { id:"manasseh", name:"Manasseh", al:["Manasseh"], t:"ot", av:"youth", desc:"Joseph's firstborn by Asenath; though older, Jacob crossed his hands to bless his younger brother Ephraim above him (Gen 41:51; 48:14-20)." },
  { id:"ephraim", name:"Ephraim", al:["Ephraim"], t:"ot", av:"youth", desc:"Joseph's second son by Asenath, given the greater blessing over his older brother Manasseh by Jacob's crossed hands (Gen 41:52; 48:14-20)." },
  { id:"rahab", name:"Rahab", al:["Rahab"], t:"ot", av:"woman", desc:"A prostitute of Jericho whose house was built into the city wall; hid Joshua's two spies from the king's men and won an oath sparing her household when the city fell (Josh 2, 6:22-25) — later named in Jesus' genealogy (Matt 1:5) and commended for faith (Heb 11:31; James 2:25)." },
  { id:"barak", name:"Barak", al:["Barak"], t:"ot", av:"warrior", desc:"Son of Abinoam of Kedesh-naphtali, summoned by Deborah to lead ten thousand men against Sisera; agreed only on condition she come with him, which cost him the honor of Sisera's death — that went to a woman instead (Judg 4:6-9) — though he is still named among the faith-heroes of Hebrews 11:32." },
  { id:"sisera", name:"Sisera", al:["Sisera"], t:"ot", av:"warrior", desc:"Commander of King Jabin of Hazor's army, based at Harosheth-hagoyim with nine hundred iron chariots; routed at the Kishon when the LORD 'threw Sisera and all his chariots... into a panic' (Judg 4:15), fled on foot to Jael's tent and was killed there in his sleep (Judg 4:17-21)." },
  { id:"jael", name:"Jael", al:["Jael"], t:"ot", av:"woman", desc:"Wife of Heber the Kenite; welcomed the fleeing Sisera into her tent with milk and a rug to hide under, then drove a tent peg through his temple with a hammer while he slept — fulfilling Deborah's word that the LORD would sell Sisera 'into the hand of a woman' (Judg 4:17-22), and celebrated in Deborah's song as 'most blessed of women' (Judg 5:24-27)." },
  { id:"delilah", name:"Delilah", al:["Delilah"], t:"ot", av:"woman", desc:"A woman of the Valley of Sorek whom Samson loved; bribed by the Philistine lords with 1,100 pieces of silver apiece to learn the secret of his strength, she wore him down through three false answers before he told her the truth about his uncut hair — then had it shaved while he slept, delivering him blind and shackled to his enemies (Judg 16:4-21)." },
  { id:"midianites", name:"Midianites (and allied raiders)", al:["Midian","Midianites","Amalekites","people of the East"], t:"ot", av:"warrior", desc:"Camel-riding desert confederation — Midian joined by Amalek and 'the people of the East' — that stripped Israel's harvests bare for seven years before Gideon's 300 routed their camp 'as thick as locusts' at the hill of Moreh (Judg 6:1-6, 33; 7:12); their princes Oreb and Zeeb are caught and killed by Ephraimite fighters at the fords of the Jordan in the rout's aftermath (Judg 7:24-25)." },
  { id:"philistine-lords", name:"The lords of the Philistines", al:["lords of the Philistines","Philistine lords"], t:"ot", av:"king", desc:"The five rulers of the Philistine pentapolis (Gaza, Ashkelon, Ashdod, Gath, Ekron) who together bribe Delilah with 1,100 pieces of silver each to learn the secret of Samson's strength (Judg 16:5); they gather to sacrifice to Dagon and put the blinded Samson on display when he is finally captured — 'about three thousand men and women' of their assembly die with him when the temple falls (Judg 16:23-30)." },
  { id:"widow-zarephath", name:"The widow of Zarephath", al:["widow of Zarephath","the widow"], t:"ot", av:"woman", desc:"A Phoenician widow gathering sticks for what she expects to be her and her son's last meal when Elijah asks her for bread and water; her jar of flour and jug of oil sustain all three through the famine, and when her son later dies, Elijah revives him on her upper-room bed — 'now I know that you are a man of God' (1 Kgs 17:8-24). Jesus later cites her, a foreigner, as proof that God's mercy was never confined to Israel (Luke 4:25-26)." },
  { id:"obadiah-steward", name:"Obadiah (Ahab's steward)", al:["Obadiah"], t:"ot", av:"official", desc:"Ahab's palace steward, 'one who feared the LORD greatly,' who hid a hundred of the LORD's prophets in two caves and fed them at his own risk during Jezebel's purge; sent by Ahab to search the land for surviving pasture, he meets Elijah on the road and, terrified Elijah will vanish again and cost him his life, is finally persuaded to carry word of Elijah's return to the king (1 Kgs 18:3-16). Not to be confused with the later minor prophet of the same name." },
  { id:"hazael", name:"Hazael", al:["Hazael"], t:"ot", av:"king", desc:"Named at Horeb as one of Elijah's three commissions — 'anoint Hazael to be king over Syria' (1 Kgs 19:15) — though it is Elisha who carries this out years later, weeping as he foresees the atrocities Hazael will commit against Israel before smothering his master Ben-hadad and seizing the Aramean throne himself (2 Kgs 8:7-15)." },
  { id:"jehu", name:"Jehu", al:["Jehu"], t:"ot", av:"warrior", desc:"Named at Horeb as the second of Elijah's three commissions — 'anoint Jehu... to be king over Israel' (1 Kgs 19:16) — fulfilled years later when Elisha's messenger anoints him in secret and he immediately drives his chariot to Jezreel, killing Joram and Jezebel and ending Ahab's dynasty in a single furious purge (2 Kgs 9)." },
  { id:"naaman", name:"Naaman", al:["Naaman"], t:"ot", av:"warrior", desc:"Aramean army commander, 'a great man with his master... a mighty man of valor,' but a leper; sent to Israel with a fortune in silver, gold, and festal garments, he is offended by Elisha's plain instruction to wash seven times in the Jordan until his own servants talk him into it — then confesses 'there is no God in all the earth but in Israel' (2 Kgs 5:1-19)." },
  { id:"gehazi", name:"Gehazi", al:["Gehazi"], t:"ot", av:"official", desc:"Elisha's servant, present at several of the prophet's miracles (2 Kgs 4). Chases down the departing Naaman with a fabricated errand to extract silver and garments for himself, lies to Elisha's face about it, and is struck with Naaman's leprosy 'forever' for turning a free gift of grace into paid profit (2 Kgs 5:20-27)." },
  { id:"sennacherib", name:"Sennacherib", al:["Sennacherib"], t:"ot", av:"king", desc:"King of Assyria (r. 705-681 BC) who invaded Judah in 701 BC and besieged Jerusalem after Hezekiah's revolt; his own inscriptions boast of shutting Hezekiah up 'like a caged bird,' but never claim the city's capture. Withdraws after the angel of the LORD strikes his camp, and is later murdered by two of his own sons while worshiping at Nineveh (2 Kgs 18-19)." },
  { id:"rabshakeh", name:"The Rabshakeh", al:["Rabshakeh"], t:"ot", av:"official", desc:"Title, not a personal name ('chief cupbearer' or high military-diplomatic officer), of the Assyrian field commander Sennacherib sends ahead with a great army to demand Jerusalem's surrender; delivers his ultimatum in Hebrew, deliberately over the heads of Hezekiah's officials, to unsettle the ordinary people listening on the wall (2 Kgs 18:17-37; 19:8-13)." },
  { id:"nebuchadnezzar", name:"Nebuchadnezzar", al:["Nebuchadnezzar"], t:"ot", av:"king", desc:"King of Babylon (r. 605-562 BC) whose armies deported Judah's elite in 597 BC and, after Zedekiah's rebellion, returned to besiege and finally destroy Jerusalem in 586 BC — burning the temple, executing Zedekiah's sons before him at Riblah, and blinding the king before marching him to Babylon in chains (2 Kgs 24-25)." },
  { id:"zedekiah", name:"Zedekiah", al:["Zedekiah","Mattaniah"], t:"ot", av:"king", desc:"Judah's last king, installed by Nebuchadnezzar under his birth name Mattaniah after Jehoiachin's deportation (2 Kgs 24:17); his rebellion brings Nebuchadnezzar's army back for a final siege. Captured fleeing near Jericho when the wall is breached, he watches his sons executed at Riblah moments before his own eyes are put out — the last thing he ever sees (2 Kgs 25:1-7)." },
  { id:"gedaliah", name:"Gedaliah", al:["Gedaliah"], t:"ot", av:"official", desc:"Judean noble appointed governor over the remnant left in the land after Jerusalem's fall; rules briefly from Mizpah, urging survivors to settle down and serve Babylon in peace, before being assassinated at a banquet by Ishmael, a member of the royal family, along with the Babylonian garrison stationed with him (2 Kgs 25:22-25)." },
  { id:"nebuzaradan", name:"Nebuzaradan", al:["Nebuzaradan"], t:"ot", av:"warrior", desc:"Captain of Nebuchadnezzar's royal guard, sent from Riblah a month after Jerusalem's wall is breached to finish the destruction — burning the temple, palace, and every great house, breaking down the city walls, and deporting all but the poorest of the land (2 Kgs 25:8-12, 18-21)." },
  { id:"jehoiachin", name:"Jehoiachin", al:["Jehoiachin","Jeconiah","Coniah"], t:"ot", av:"king", desc:"Judah's king for three months at eighteen, deported to Babylon in 597 BC when Nebuchadnezzar first took Jerusalem (2 Kgs 24:8-15); spends thirty-seven years a captive before Evil-merodach releases him, seats him above the other exiled kings, and gives him a regular allowance 'as long as he lived' — the book of Kings' final, unexpectedly hopeful note (2 Kgs 25:27-30)." },
  { id:"evil-merodach", name:"Evil-merodach", al:["Evil-merodach"], t:"ot", av:"king", desc:"Nebuchadnezzar's son and successor as king of Babylon (r. 562-560 BC); in his first year as king he pardons the long-imprisoned Jehoiachin, elevates him above the other captive kings in Babylon, and grants him a lifelong daily allowance — closing 2 Kings on an unexpected note of mercy (2 Kgs 25:27-30)." },
  { id:"zerubbabel", name:"Zerubbabel", al:["Zerubbabel"], t:"ot", av:"official", desc:"Grandson of the exiled King Jehoiachin and Persian-appointed governor of Judah; leads the first wave of returned exiles home with the high priest Jeshua, rebuilds the altar, and lays the temple's foundation despite local opposition (Ezra 2-5) — later addressed directly in Zechariah's oracle, 'not by might, nor by power, but by my Spirit' (Zech 4:6)." },
  { id:"jeshua-priest", name:"Jeshua (the high priest)", al:["Jeshua","Joshua son of Jozadak","Jeshua son of Jozadak"], t:"ot", av:"priest", desc:"High priest among the first returning exiles, grandson of Seraiah, the last high priest before the exile, executed at Riblah (2 Kgs 25:18-21); together with Zerubbabel he rebuilds the altar, restarts the daily offerings, and lays the temple's foundation (Ezra 3), and is later crowned symbolically in Zechariah's vision as a sign of the coming priest-king (Zech 3; 6:11-13). Not to be confused with Joshua son of Nun." },
  { id:"artaxerxes", name:"Artaxerxes I", al:["Artaxerxes"], t:"ot", av:"king", desc:"Persian king (r. 465-424 BC) who authorizes Ezra's mission to teach the Law (Ezra 7) and, years later, grants his own cupbearer Nehemiah leave, letters of passage, and timber to rebuild Jerusalem's walls (Neh 2:1-8) — later briefly recalling him to Susa before sending him back for a second term (Neh 13:6-7)." },
  { id:"sanballat", name:"Sanballat the Horonite", al:["Sanballat"], t:"ot", av:"official", desc:"Governor of Samaria and the chief opponent of Nehemiah's wall project, first merely 'displeased' (Neh 2:10) then openly mocking ('what is this feeble thing they build?', Neh 4:2) and eventually plotting against Nehemiah through a string of false invitations and rumors (Neh 6:1-14). A Persian-period governor named Sanballat is independently attested in the Elephantine papyri." },
  { id:"tobiah", name:"Tobiah the Ammonite", al:["Tobiah"], t:"ot", av:"official", desc:"An official 'servant' with Ammonite ties and marriage connections into Jerusalem's own priestly and noble families (Neh 6:17-19; 13:4), who joins Sanballat in mocking and opposing the wall from the earliest news of the project (Neh 2:10, 19) through Nehemiah's later, furious eviction of him from a temple storeroom he had been given (Neh 13:4-9)." },
  { id:"mordecai", name:"Mordecai", al:["Mordecai"], t:"ot", av:"official", desc:"A Benjamite exile serving at the king's gate in Susa, descended from those carried off from Jerusalem with King Jeconiah (Esth 2:5-6); raises his orphaned cousin Esther as his own daughter, refuses to bow to Haman, and, on learning of Haman's genocidal decree, presses the reluctant Esther to risk her life interceding with the king — 'who knows whether you have not come to the kingdom for such a time as this?' (Esth 4:14)." },
  { id:"haman", name:"Haman", al:["Haman"], t:"ot", av:"official", desc:"An Agagite elevated above all the king's other officials, whose fury at Mordecai's refusal to bow escalates into a bribed decree to annihilate every Jew in the empire on a single day (Esth 3); the plot he builds to hang Mordecai ultimately hangs him instead, on the very gallows he raised (Esth 7:9-10)." },
  { id:"ahasuerus", name:"Ahasuerus (Xerxes I)", al:["Ahasuerus","Xerxes","Xerxes I"], t:"ot", av:"king", desc:"Persian king (r. 486-465 BC) who rules from Susa over 127 provinces 'from India to Cush' (Esth 1:1); deposes Queen Vashti for refusing to appear at his banquet, then chooses the orphan Esther as her replacement without learning she is Jewish — and later signs, then reverses, Haman's decree against her people at her repeated, risked appeals." },
  { id:"hathach", name:"Hathach", al:["Hathach"], t:"ot", av:"official", desc:"One of the king's eunuchs assigned to attend Queen Esther; carries messages between her and the mourning Mordecai at the king's gate, relaying Haman's decree and Mordecai's urgent plea that she intercede with the king (Esth 4:5-10)." },
  { id:"ha-satan", name:"The satan (the Accuser)", al:["Satan","the Satan","the accuser","the adversary"], t:"ot", av:"traveler", desc:"Not a proper name here but a title — Hebrew 'ha-satan', 'the accuser' or 'the adversary' — one member of the heavenly council ('the sons of God') who comes 'from going to and fro on the earth, and from walking up and down on it' and twice challenges Job's motives before the LORD, first over his possessions, then over his own body (Job 1:6-12; 2:1-7). Kept distinct here (id disambiguated from any later New Testament 'Satan' entry) because the book of Job never gives this figure the fully personalized tempter/devil identity later tradition reads back into the scene — he acts only by God's explicit, bounded permission." },
  { id:"eliphaz", name:"Eliphaz the Temanite", al:["Eliphaz"], t:"ot", av:"elder", desc:"The first and most senior of Job's three friends, from Teman in Edom; opens the cycle of dialogues (Job 4-5) arguing from personal spiritual experience that the innocent do not simply perish and that Job's suffering must trace back to hidden sin, a position he repeats and hardens across two more speeches (Job 15, 22)." },
  { id:"bildad", name:"Bildad the Shuhite", al:["Bildad"], t:"ot", av:"elder", desc:"Second of Job's three friends, from Shuah; leans on inherited tradition and proverb rather than personal experience, arguing that Job's children died for their own sin and that God 'does not reject a blameless man' (Job 8, 18, 25) — his final speech is the shortest of the three, as the friends' case visibly runs out of road." },
  { id:"zophar", name:"Zophar the Naamathite", al:["Zophar"], t:"ot", av:"elder", desc:"Third and bluntest of Job's three friends, from Naamah; accuses Job outright of wickedness worse than he admits and insists God is already showing him mercy by punishing less than he deserves (Job 11, 20) — he has no third speech in the text as it stands, the dialogue cycle breaking down before his expected final turn." },
  { id:"job-wife", name:"Job's wife", al:["his wife","Job's wife"], t:"ot", av:"woman", desc:"Unnamed throughout the book; watching her husband stripped of everything and then struck with sores, she urges him to 'curse God and die' rather than keep clinging to his integrity — Job rebukes her as speaking 'like one of the foolish women' but is not recorded as blaming or dismissing her further (Job 2:9-10)." },
  { id:"job-messengers", name:"Job's four messengers", al:["messenger","the messenger"], t:"ot", av:"traveler", desc:"Four unnamed servants who arrive at Job's home in rapid, overlapping succession — each interrupting the last mid-sentence — to report the Sabean raid, the fire from heaven, the Chaldean raid, and finally the great wind that killed all ten of Job's children; each closes with the same refrain, 'I alone have escaped to tell you' (Job 1:13-19)." },
  { id:"babylonian-exiles", name:"The Babylonian exiles", al:["exiles","captives","we"], t:"ot", av:"traveler", desc:"The deportee community carried off after Jerusalem's fall (2 Kgs 25:8-12), settled on Babylonia's irrigation canals — the same setting Ezekiel names 'by the Chebar canal' (Ezek 1:1) — and given collective voice in Psalm 137's grief, refusal to perform temple songs for their captors, and vow never to forget Jerusalem." },
  { id:"hananiah-prophet", name:"Hananiah son of Azzur", al:["Hananiah"], t:"ot", av:"prophet", desc:"A prophet from Gibeon who publicly breaks the wooden yoke off Jeremiah's neck in the temple, predicting Babylon's power broken and the exiles home within two years (Jer 28:1-11); Jeremiah answers that only time will show whose word the LORD sent, and within two months Hananiah is dead, exactly as Jeremiah foretold (Jer 28:15-17) — the failed prediction whose shadow still hangs over the exiles when Jeremiah's letter of ch. 29 reaches them. Kept distinct from any other Hananiah in Scripture, disambiguated per this dataset's naming convention." },
  { id:"ahab-prophet", name:"Ahab son of Kolaiah", al:["Ahab son of Kolaiah"], t:"ot", av:"prophet", desc:"One of two prophets active among the Babylonian exiles whom Jeremiah's letter denounces by name for prophesying lies in the LORD's name and for adultery with their neighbors' wives; Jeremiah foretells that Nebuchadnezzar will execute both men by fire, giving rise to a byword — 'may the LORD make you like Zedekiah and Ahab, whom the king of Babylon roasted in the fire' (Jer 29:21-23). Disambiguated from King Ahab of Israel (1 Kgs 16-22), an unrelated figure centuries earlier." },
  { id:"zedekiah-prophet", name:"Zedekiah son of Maaseiah", al:["Zedekiah son of Maaseiah"], t:"ot", av:"prophet", desc:"The second of the two false prophets among the Babylonian exiles condemned alongside Ahab son of Kolaiah in Jeremiah's letter — executed by Nebuchadnezzar and remembered in the exiles' own curse-formula (Jer 29:21-23). Disambiguated from King Zedekiah of Judah, Judah's last king, an entirely different person reigning back in Jerusalem at the same time." },
  { id:"shemaiah-nehelamite", name:"Shemaiah the Nehelamite", al:["Shemaiah"], t:"ot", av:"prophet", desc:"A false prophet among the Babylonian exiles who, angered by Jeremiah's letter, writes back to the priest Zephaniah in Jerusalem demanding Jeremiah be put in stocks as a madman; Jeremiah's counter-oracle pronounces that Shemaiah will leave no descendants among the people and will not live to see the good the LORD does for them, 'because he has preached rebellion against the LORD' (Jer 29:24-32)." },
  { id:"shadrach-meshach-abednego", name:"Shadrach, Meshach and Abednego", al:["Shadrach","Meshach","Abednego","Hananiah","Mishael","Azariah"], t:"ot", av:"official", desc:"Three Judean nobles deported with Daniel in 605 BC and renamed from their Hebrew names — Hananiah, Mishael, and Azariah — to honor Babylonian gods (Dan 1:6-7); they join Daniel in refusing the king's food and wine (Dan 1:8-16) and are later promoted to administer the province of Babylon (Dan 2:49). When Nebuchadnezzar's golden image on the plain of Dura demands worship, the three alone refuse to bow, are denounced by Chaldean rivals, and are thrown into a furnace heated seven times hotter than usual — from which they walk out unbound and unsinged, not even smelling of smoke, after a fourth figure 'like a son of the gods' is seen walking with them in the flames (Dan 3)." },
  { id:"babylonian-magicians", name:"Babylon's magicians, enchanters and Chaldeans", al:["magicians","enchanters","sorcerers","Chaldeans","wise men","astrologers"], t:"ot", av:"official", desc:"The court's professional guild of dream-interpreters and omen-readers, gathered whenever Nebuchadnezzar needs an answer his own wisdom cannot supply; they fail Daniel's opening test outright — unable even to state the king's forgotten dream, let alone interpret it, and confess to the king's face that 'no one can tell it except the gods, whose dwelling is not with flesh' (Dan 2:10-11) — and are spared execution only when Daniel succeeds where they could not (Dan 2:24). Some of their number later denounce Shadrach, Meshach and Abednego for refusing to worship the golden image (Dan 3:8-12). By the end of Daniel's training, the king finds him and his three friends 'ten times better' in every matter of wisdom than all of this guild combined (Dan 1:20)." }
];
